    + 'Kallangur QLD 4503</p></div></body></html>';
}
function row(label, value) {
  return '<tr><th align="left" style="padding:4px 12px 4px 0;vertical-align:top">' + esc(label)
    + '</th><td style="padding:4px 0">' + esc(value) + '</td></tr>';
}
// ---- end common.js

