  return '<table>'
    + [['Name', q.name], ['Email', q.email], ['Organisation', q.org || '-'], ['Reason', q.reason],
      ['Investor area requested', q.wants_investor ? 'Yes' : 'No'], ['NDA version', q.nda_version],
